package com.franco.desco.adapter.in.web.evaluation;import com.franco.desco.adapter.in.security.JwtSessionIdentityResolver;import com.franco.desco.adapter.in.web.common.*;import com.franco.desco.adapter.in.web.common.idempotency.IdempotentOperation;import com.franco.desco.adapter.in.web.common.pagination.PageResponse;import com.franco.desco.adapter.in.web.openapi.OpenApiConstants;import com.franco.desco.application.evaluation.*;import com.franco.desco.application.evaluation.port.in.EvaluationUseCase;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.time.Instant;
@RestController@RequestMapping("/api/v1/evaluaciones")@Tag(name="Evaluaciones agronómicas",description="Evaluaciones técnicas y mediciones de materia seca.")@SecurityRequirement(name=OpenApiConstants.BEARER_AUTH)@Validated public class EvaluationController{private final EvaluationUseCase u;private final EvaluationWebMapper map;private final ApiResponseFactory res;private final ClientRequestContextResolver meta;private final JwtSessionIdentityResolver ids;public EvaluationController(EvaluationUseCase u,EvaluationWebMapper map,ApiResponseFactory res,ClientRequestContextResolver meta,JwtSessionIdentityResolver ids){this.u=u;this.map=map;this.res=res;this.meta=meta;this.ids=ids;}
 @GetMapping@PreAuthorize("@permissionGuard.has(authentication,'EVALUACIONES_LISTAR')")@Operation(operationId="evaluacionesListar",summary="Listar evaluaciones")public ResponseEntity<ApiResponse<PageResponse<EvaluationResponses.Summary>>>list(@RequestParam(required=false)Long visitaTecnicaId,@RequestParam(required=false)Long parcelaCultivoId,@RequestParam(required=false)Integer tipoEvaluacionId,@RequestParam(required=false)Instant fechaDesde,@RequestParam(required=false)Instant fechaHasta,@RequestParam(defaultValue="1")@Min(1)int pagina,@RequestParam(defaultValue="20")@Min(1)@Max(200)int tamano,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.list(map.list(pagina,tamano,visitaTecnicaId,parcelaCultivoId,tipoEvaluacionId,fechaDesde,fechaHasta),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @GetMapping("/{id}")@PreAuthorize("@permissionGuard.has(authentication,'EVALUACIONES_VER')")@Operation(operationId="evaluacionesVer",summary="Ver evaluación")public ResponseEntity<ApiResponse<EvaluationResponses.Detail>>get(@PathVariable Long id,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.get(new EvaluationCommands.Get(id),ids.resolve(a),meta.resolve(r)),r,map::response);}
 @PostMapping@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'EVALUACIONES_CREAR')")@Operation(operationId="evaluacionesCrear",summary="Registrar evaluación")public ResponseEntity<ApiResponse<EvaluationResponses.Created>>create(@Valid@RequestBody EvaluationRequests.Create q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.create(new EvaluationCommands.Create(q.visitaTecnicaId(),q.parcelaCultivoId(),q.tipoEvaluacionId(),q.fechaHora(),q.resultado(),q.observacion(),map.dm(q.materiaSeca())),ids.resolve(a),meta.resolve(r)),r,EvaluationResponses.Created::new);}
 @PutMapping("/{id}")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'EVALUACIONES_EDITAR')")@Operation(operationId="evaluacionesEditar",summary="Editar evaluación")public ResponseEntity<ApiResponse<Void>>update(@PathVariable Long id,@Valid@RequestBody EvaluationRequests.Update q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.update(new EvaluationCommands.Update(id,q.parcelaCultivoId(),q.tipoEvaluacionId(),q.fechaHora(),q.resultado(),q.observacion(),map.dm(q.materiaSeca())),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/materia-seca")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'EVALUACIONES_CREAR')")@Operation(operationId="evaluacionesMateriaSecaRegistrar",summary="Registrar materia seca")public ResponseEntity<ApiResponse<Void>>dry(@PathVariable Long id,@Valid@RequestBody EvaluationRequests.RegisterDryMatter q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.registerDryMatter(new EvaluationCommands.RegisterDryMatter(id,q.porcentajeMateriaSeca(),q.numeroMuestras()),ids.resolve(a),meta.resolve(r)),r);}}
